const id = uuidv1();
// '719f9b5c-b984-11ed-afa1-0242ac120002'`},v3:{title:"UUID v3",desc:"MD5 hash based on a namespace and string. Consistent output for given inputs.",details:"Generates a deterministic UUID using MD5 hashing of a namespace and name. If you use the same namespace and name, you'll always get the same UUID.",algorithm:"Computes the MD5 hash of a namespace UUID concatenated with a name string. The resulting 128-bit hash is modified to set the version (3) and variant bits.",useCase:"When you need reproducible identifiers across different systems or runs, mapped from unique names (like a URL, FQDN, or object ID).",example:"a3bb189e-8bf9-3888-9912-ace4e6543002",guideCodeExample:`import { v3 as uuidv3 } from 'uuid';

